def q(id, difficulty, passage, question, choices, answer, explanation, tags):
    return {
        **BASE,
        "id": id,
        "difficulty": difficulty,
        "passage": passage,
        "question": question,
        "choices": choices,
        "answer": answer,
        "explanation": explanation,
        "tags": tags,
    }


